205	func normalizeEvent(raw []byte) (*NormalizedEvent, error) {
206		if err := checkCharacterIntegrity(raw); err != nil {
207			return nil, err
208		}
209		object, err := decodeObject(raw)
210		if err != nil {
211			return nil, err
212		}
213	
214		// Sort source keys so candidate order (and therefore error messages) is
215		// deterministic regardless of Go map iteration order.
216		keys := make([]string, 0, len(object))
217		for key := range object {
218			keys = append(keys, key)
219		}
220		sort.Strings(keys)
221	
222		groups := make(map[string][]fieldCandidate)
223		extra := make(map[string]json.RawMessage)
224		for _, key := range keys {
225			switch key {
226			case FieldTimestamp, FieldSourceIP, FieldAction:
227				groups[key] = append(groups[key], fieldCandidate{from: key, raw: object[key]})
228			default:
229				if canonical, ok := fieldAliases[key]; ok {
230					groups[canonical] = append(groups[canonical], fieldCandidate{from: key, raw: object[key]})
231				} else {
232					extra[key] = object[key]
233				}
234			}
235		}
236	
237		values := make(map[string]string)
238		for _, canonical := range canonicalFieldOrder {
239			candidates := groups[canonical]
240			if len(candidates) == 0 {
241				continue
242			}
243			var canonicalValue string
244			for i, candidate := range candidates {
245				value, err := normalizeFieldValue(canonical, candidate.raw)
246				if err != nil {
247					return nil, err
248				}
249				if i == 0 {
250					canonicalValue = value
251					continue
252				}
253				// Every candidate must be valid; consistent values merge and
254				// divergent values fail the whole line.
255				if value != canonicalValue {
256					return nil, fmt.Errorf("field %q has conflicting values: %q and %q", canonical, canonicalValue, value)
257				}
258			}
259			values[canonical] = canonicalValue
260		}
261	
262		timestamp, ok := values[FieldTimestamp]
263		if !ok {
264			return nil, fmt.Errorf("missing required field %q", FieldTimestamp)
265		}
266		action, ok := values[FieldAction]
267		if !ok {
268			return nil, fmt.Errorf("missing required field %q", FieldAction)
269		}
270	
271		event := &NormalizedEvent{
272			Timestamp: timestamp,
273			Action:    action,
274		}
275		if sourceIP, present := values[FieldSourceIP]; present {
276			event.SourceIP = sourceIP
277		}
278		if len(extra) > 0 {
279			event.Extra = extra
280		}
281		return event, nil
282	}
283	
284	// checkCharacterIntegrity rejects log lines whose characters cannot be
285	// represented exactly. The raw bytes must be valid UTF-8, and every \uXXXX
286	// escape inside a JSON string — field names and string values at any depth,
287	// including unmapped fields and an input's own extra — must denote a Unicode
